{
  "root": "main_stack",
  "state": {
    "campaignRoadmap": [
      {
        "Week": "Week 1",
        "Phase": "Strategy & Planning",
        "Primary Milestone": "Strategy Approval",
        "Lead Role": "Project Manager"
      },
      {
        "Week": "Weeks 2-5",
        "Phase": "Creative Production",
        "Primary Milestone": "Asset Creation",
        "Lead Role": "Graphic Designer"
      },
      {
        "Week": "Week 6",
        "Phase": "Pilot Testing",
        "Primary Milestone": "A/B Testing Results",
        "Lead Role": "Data Analyst"
      },
      {
        "Week": "Week 7",
        "Phase": "Campaign Launch",
        "Primary Milestone": "Full Launch",
        "Lead Role": "Project Manager"
      },
      {
        "Week": "Weeks 8-9",
        "Phase": "Optimization",
        "Primary Milestone": "Performance Tweak",
        "Lead Role": "Data Analyst"
      },
      {
        "Week": "Week 10",
        "Phase": "Final Reporting",
        "Primary Milestone": "Performance Report",
        "Lead Role": "Data Analyst"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "main_title_stack",
        "overview_card",
        "roadmap_title_stack",
        "roadmap_card",
        "budget_risk_title",
        "budget_risk_stack",
        "quick_actions_title",
        "quick_actions_stack"
      ]
    },
    "main_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "main_title_icon",
        "main_title_text"
      ]
    },
    "main_title_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/shop.svg"
      },
      "children": []
    },
    "main_title_text": {
      "type": "Text",
      "props": {
        "text": "Digital Marketing Campaign Overview",
        "variant": "h1"
      },
      "children": []
    },
    "overview_card": {
      "type": "Card",
      "props": {},
      "children": [
        "overview_content_stack"
      ]
    },
    "overview_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "overview_image",
        "overview_text_1",
        "overview_text_2"
      ]
    },
    "overview_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Social_media_marketing.jpg/1200px-Social_media_marketing.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "overview_text_1": {
      "type": "Text",
      "props": {
        "text": "A 10-week comprehensive digital growth strategy with a total budget of $15,000 USD."
      },
      "children": []
    },
    "overview_text_2": {
      "type": "Text",
      "props": {
        "text": "The campaign transitions from creative asset production to data-driven A/B testing and full-scale launch."
      },
      "children": []
    },
    "roadmap_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "roadmap_title_icon",
        "roadmap_title_text"
      ]
    },
    "roadmap_title_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/calendar.svg"
      },
      "children": []
    },
    "roadmap_title_text": {
      "type": "Text",
      "props": {
        "text": "10-Week Campaign Roadmap",
        "variant": "h2"
      },
      "children": []
    },
    "roadmap_card": {
      "type": "Card",
      "props": {},
      "children": [
        "roadmap_content_stack"
      ]
    },
    "roadmap_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "roadmap_image",
        "roadmap_table"
      ]
    },
    "roadmap_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Laptop_on_desk.jpg/1200px-Laptop_on_desk.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "roadmap_table": {
      "type": "Table",
      "props": {
        "statePath": "/campaignRoadmap",
        "columns": [
          {
            "key": "Week",
            "label": "Week"
          },
          {
            "key": "Phase",
            "label": "Phase"
          },
          {
            "key": "Primary Milestone",
            "label": "Primary Milestone"
          },
          {
            "key": "Lead Role",
            "label": "Lead Role"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "Week",
        "highlightColumns": [
          "Primary Milestone"
        ]
      },
      "children": []
    },
    "budget_risk_title": {
      "type": "Text",
      "props": {
        "text": "Budget Allocation & Risk Mitigation",
        "variant": "h3"
      },
      "children": []
    },
    "budget_risk_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "budget_text",
        "risk1_text",
        "risk2_text",
        "risk3_text"
      ]
    },
    "budget_text": {
      "type": "Text",
      "props": {
        "text": "Budget: Ad Spend ($10,000), Software Tools ($2,000), Contingency ($3,000)."
      },
      "children": []
    },
    "risk1_text": {
      "type": "Text",
      "props": {
        "text": "Risk 1: Asset production bottleneck. Mitigation: Utilize pre-approved templates for faster design iterations."
      },
      "children": []
    },
    "risk2_text": {
      "type": "Text",
      "props": {
        "text": "Risk 2: Low ad conversion rates. Mitigation: Daily budget re-allocation during Week 6 based on A/B performance."
      },
      "children": []
    },
    "risk3_text": {
      "type": "Text",
      "props": {
        "text": "Risk 3: Platform outages. Mitigation: Diversify ad spend across three independent social media platforms."
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md"
      },
      "children": [
        "budget_tracker_button",
        "ad_manager_button"
      ]
    },
    "budget_tracker_button": {
      "type": "Button",
      "props": {
        "label": "View Budget Tracker"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://docs.google.com/spreadsheets/d/1A2B3C4D5E6F7G8H9I0J/edit"
          }
        }
      },
      "children": []
    },
    "ad_manager_button": {
      "type": "Button",
      "props": {
        "label": "Access Ad Manager"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://admanager.com/dashboard"
          }
        }
      },
      "children": []
    }
  }
}
